const $=s=>document.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cities=[{name:'大理',icon:'⛰',desc:'洱海骑行 · 古城漫游 · 日落发呆',daily:420,travel:700},{name:'杭州',icon:'🌿',desc:'西湖散步 · 山野喝茶 · 城市漫游',daily:340,travel:250},{name:'成都',icon:'🍵',desc:'熊猫基地 · 茶馆慢生活 · 巷子觅食',daily:360,travel:600}];
const seed=()=>({title:'去有风的地方',start:'2027-06-18',days:4,city:'大理',members:[{id:'a',name:'Ashley',budget:3000,start:'2027-06-18',end:'2027-06-24',city:'大理',pace:'轻松慢游'},{id:'b',name:'小林',budget:2500,start:'2027-06-18',end:'2027-06-22',city:'大理',pace:'轻松慢游'},{id:'c',name:'阿杰',budget:2200,start:'2027-06-19',end:'2027-06-23',city:'成都',pace:'充实打卡'},{id:'d',name:'可可',budget:2800,start:'2027-06-18',end:'2027-06-24',city:'杭州',pace:'轻松慢游'}],events:[],expenses:[{id:'e1',name:'民宿订金',amount:800,payer:'a',people:['a','b','c','d']},{id:'e2',name:'行前聚餐',amount:240,payer:'b',people:['a','b','c']}],done:[]});
let state=seed(),tab='overview',storageOK=true;try{const raw=localStorage.getItem('gradtrip-v1');if(raw)state=validate(JSON.parse(raw));const shared=new URLSearchParams(location.search).get('trip');if(shared){state=validate(JSON.parse(decodeURIComponent(escape(atob(shared)))));history.replaceState({},'',location.pathname);}}catch(e){state=seed()}
function validate(v){if(!v||!Array.isArray(v.members)||v.members.length>30||!Array.isArray(v.expenses)||!Array.isArray(v.events)||!cities.some(c=>c.name===v.city)||!Number.isInteger(v.days)||v.days<1||v.days>14)throw Error('invalid');return v}
function save(){try{localStorage.setItem('gradtrip-v1',JSON.stringify(state))}catch{storageOK=false;toast('本机存储不可用，请导出计划备份')}render()}
const money=n=>'¥'+Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2});const uid=()=>Math.random().toString(36).slice(2,10);const member=id=>state.members.find(m=>m.id===id)?.name||'已移除成员';
const budget=()=>state.members.length?Math.min(...state.members.map(m=>+m.budget)):0;const estimate=c=>c.daily*state.days+c.travel;
function overlap(){if(!state.members.length)return null;const start=state.members.map(m=>m.start).sort().at(-1),end=state.members.map(m=>m.end).sort()[0];return {start,end,days:Math.floor((Date.parse(end)-Date.parse(start))/86400000)+1}}
function cityScore(c){if(!state.members.length)return 0;let vote=state.members.filter(m=>m.city===c.name).length/state.members.length;let affordable=state.members.filter(m=>m.budget>=estimate(c)).length/state.members.length;return Math.round(vote*50+affordable*50)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function title(en,cn,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">${en}</div><h1>${cn}</h1><div class="muted">${sub}</div></div>${action}</div>`}
function warnings(){let o=overlap(),out=[];if(!state.members.length)out.push('先添加至少一位成员，再比较预算与时间。');if(o&&o.days<state.days)out.push(o.days>0?`共同空闲仅 ${o.days} 天，短于计划的 ${state.days} 天，请调整日期或行程天数。`:'成员之间没有共同空闲日期，请先协商时间。');const finish=new Date(state.start+'T00:00:00Z');finish.setUTCDate(finish.getUTCDate()+state.days-1);if(o&&o.days>=state.days&&(state.start<o.start||finish.toISOString().slice(0,10)>o.end))out.push(`当前出发日期未落在所有成员的共同窗口内，建议从 ${o.start} 起安排 ${state.days} 天。`);let c=cities.find(c=>c.name===state.city);if(state.members.length&&estimate(c)>budget())out.push(`${state.city}参考人均 ${money(estimate(c))}，超出最低预算 ${money(estimate(c)-budget())}；可切换目的地或缩短天数。`);return out.map(t=>`<div class="notice">⚑ ${t}</div>`).join('')}
function overview(){let c=cities.find(c=>c.name===state.city),total=state.expenses.reduce((s,e)=>s+e.amount,0);return title('MAKE MEMORIES, TOGETHER','把想去，变成一起去。','毕业不散场，下一站我们一起出发。',`<button class="btn" onclick="tripForm()">⚙ 旅行设置</button>`)+`<section class="hero"><div class="hero-content"><span class="tag">2027 毕业旅行计划</span><h2>${esc(state.title)}<br>这一程，一个都不少。</h2><p>${esc(state.start)} 出发 · ${state.days} 天 · 意向 ${esc(state.city)}<br>把不同的期待，拼成一段共同的回忆。</p><button class="btn primary small" onclick="setTab('team')">一起决定去哪 ↗</button></div><div class="hero-art"><svg viewBox="0 0 500 270" xmlns="http://www.w3.org/2000/svg" aria-label="山野湖泊插画" role="img"><circle cx="355" cy="67" r="33" fill="#eedca8"/><path d="M20 244L170 69 284 212 365 103 500 248Z" fill="#afbea0"/><path d="M170 69l-38 46 34-7 26 18 14-13z" fill="#e4e9dc"/><path d="M0 244L90 157 204 251 325 155 500 239V270H0" fill="#7c9b7b"/><path d="M0 242q160-35 250 5t250-4v27H0" fill="#b7ccbf"/><path d="M366 270q-95-35-73-77" stroke="#f2ecd8" stroke-width="15" fill="none"/><g stroke="#486748" stroke-width="5"><path d="M417 225v-67m-19 35 19-30 19 30m-32-16 13-24 13 24"/><path d="M457 240v-47m-14 24 14-25 14 25"/></g><path d="M270 206l12-22 14 22z" fill="#d59366"/><path d="M275 206l7-13 8 13" fill="#f2d6b7"/><path d="M41 62q13-12 23 0 13-12 23 0" fill="none" stroke="#7e9273" stroke-width="2"/></svg></div></section><div class="stats"><div class="stat"><div class="stat-top">已集结伙伴 <span>♧</span></div><strong>${state.members.length}</strong><small>位同学</small></div><div class="stat"><div class="stat-top">最低预算上限 <span>◈</span></div><strong>${money(budget())}</strong><small>/ 人</small></div><div class="stat"><div class="stat-top">计划时长 <span>▤</span></div><strong>${state.days}</strong><small>天的回忆</small></div><div class="stat"><div class="stat-top">已记录共同支出 <span>⇄</span></div><strong>${money(total)}</strong><small>可追溯</small></div></div>${warnings()}<div class="grid"><section class="card"><div class="section-head"><h2>下一站，一起决定</h2><span class="pill">偏好 + 预算</span></div><div class="destination-list">${[...cities].sort((a,b)=>cityScore(b)-cityScore(a)).map(cityCard).join('')}</div><p class="explain">共识分 = 目的地支持率 × 50% + 预算可承受率 × 50%。参考费用包含交通、住宿、餐饮与活动，不是实时报价。</p></section><section class="card"><div class="section-head"><h2>出发前的小事</h2><span class="muted">${state.done.length}/4 已完成</span></div><div class="progress"><i style="width:${state.done.length/4*100}%"></i></div>${['邀请同学，收集预算与时间','投票确定目的地','检查并确认每日行程','预订交通住宿，约定退款规则'].map((s,i)=>`<label class="todo inline"><input type="checkbox" ${state.done.includes(i)?'checked':''} onchange="toggleDone(${i})"><span>${s}</span></label>`).join('')}<p class="explain">共识优先于预订：先照顾预算最低、时间最紧的伙伴，再确定方案。</p></section></div><div class="bottom-callout"><div><h3>让每个人的期待，都被看见。</h3><p class="muted">${state.members.length} 位伙伴，${overlap()?.days>0?'共同空闲 '+overlap().days+' 天':'等待时间共识'}，一起选一个更合适的答案。</p></div><button class="btn small" onclick="setTab('team')">查看成员偏好 →</button></div>`}
function cityCard(c){return `<div class="destination ${state.city===c.name?'selected':''}"><div class="city-art">${c.icon}</div><div class="city-info"><h3>${c.name} ${state.city===c.name?'<span class="pill">当前意向</span>':''}</h3><div class="muted">${c.desc}</div><div class="muted">${money(estimate(c))}/人 · ${state.members.filter(m=>m.city===c.name).length} 票 ${estimate(c)>budget()?'· 预算待协商':''}</div></div><div class="score"><strong>${cityScore(c)}<small style="font-size:10px"> 分</small></strong><button class="text" onclick="chooseCity('${c.name}')">${state.city===c.name?'已选择 ✓':'选择此地 →'}</button></div></div>`}
function team(){let o=overlap();return title('A PLACE FOR EVERYONE','不同期待，同一个方向。','收集每位伙伴的真实限制，不用再反复翻聊天记录。',`<button class="btn primary" onclick="memberForm()">＋ 添加成员</button>`)+warnings()+`<div class="card" style="margin-bottom:20px"><h2>共同空闲窗口</h2><div class="muted">${o&&o.days>0?`${esc(o.start)} 至 ${esc(o.end)} · 共 ${o.days} 天`:'暂无共同时间，请调整成员可出行日期'}</div><div class="explain">个人预算为整趟旅行上限；修改成员信息后，目的地共识分会自动更新。</div></div><div class="members">${state.members.map(m=>`<div class="member-card"><div class="member-top"><span class="avatar">${esc(m.name.slice(0,1))}</span><h3>${esc(m.name)}</h3><button class="text" onclick="memberForm('${m.id}')">编辑</button></div><div class="row"><span>整趟预算</span><strong>${money(m.budget)}</strong></div><div class="row"><span>想去哪里</span><span>${esc(m.city)}</span></div><div class="row"><span>旅行节奏</span><span>${esc(m.pace)}</span></div><div class="muted">${esc(m.start)} — ${esc(m.end)}</div></div>`).join('')}</div><div class="bottom-callout"><div><h3>谁来做最终决定？</h3><p class="muted">工具提供透明建议，最后由所有成员共同确认。</p></div><button class="btn small" onclick="setTab('overview')">查看共识排名 →</button></div>`}
function plan(){return title('LESS PLANNING, MORE LIVING','把远方，排进日历。','先有一份能讨论的计划，再一起把细节补全。',`<button class="btn primary" onclick="generatePlan()">✧ 生成行程草案</button>`)+warnings()+`<section class="card"><div class="section-head"><h2>${esc(state.city)} · ${state.days}天旅行</h2><span class="ai-label">规则规划演示 · 未接实时模型</span></div><p class="muted">根据目的地、天数与多数人的旅行节奏生成模板；景点开放、交通及价格需自行核实。</p><button class="btn small" onclick="eventForm()">＋ 手动添加安排</button>${state.events.length?Array.from({length:state.days},(_,d)=>`<section class="plan-day"><h3>DAY ${String(d+1).padStart(2,'0')} <span class="muted">${dateAt(d)}</span></h3>${state.events.filter(e=>e.day===d+1).sort((a,b)=>a.time.localeCompare(b.time)).map(e=>`<div class="plan-event"><time>${esc(e.time)}</time><div class="event-text"><h3>${esc(e.name)}</h3><div class="muted">${esc(e.note)}</div></div><span class="cost">参考 ${money(e.cost)}/人</span><div class="event-actions"><button class="icon" onclick="eventForm('${e.id}')" aria-label="编辑安排">✎</button><button class="icon" onclick="removeEvent('${e.id}')" aria-label="删除安排">×</button></div></div>`).join('')||'<div class="muted">留一点空白，等大家一起补充。</div>'}</section>`).join(''):'<div class="empty">还没有安排。点击「生成行程草案」，先把旅行画出来。<br><span class="muted">不会预订，也不会产生费用。</span></div>'}</section>`}
function dateAt(d){const date=new Date(state.start+'T00:00:00');date.setDate(date.getDate()+d);return `${date.getMonth()+1}月${date.getDate()}日`}
function balances(){const b=Object.fromEntries(state.members.map(m=>[m.id,0]));for(const e of state.expenses){const cents=Math.round(e.amount*100),base=Math.floor(cents/e.people.length),rem=cents%e.people.length;b[e.payer]+=cents;e.people.forEach((id,i)=>b[id]-=base+(i<rem?1:0))}return b}
function settlements(){const b=balances(),debt=Object.entries(b).filter(([,v])=>v<0).map(([id,v])=>({id,v:-v})),credit=Object.entries(b).filter(([,v])=>v>0).map(([id,v])=>({id,v})),out=[];for(const d of debt)for(const c of credit){const v=Math.min(d.v,c.v);if(v){out.push({from:d.id,to:c.id,v:v/100});d.v-=v;c.v-=v}}return out}
function expenses(){return title('GOOD FRIENDS, CLEAR ACCOUNTS','快乐一起，账也算清。','谁先付、谁参与、谁该补给谁，每一笔都透明。',`<button class="btn primary" onclick="expenseForm()">＋ 记一笔</button>`)+`<div class="grid"><section class="card"><div class="section-head"><h2>共同支出</h2><span class="pill">合计 ${money(state.expenses.reduce((s,e)=>s+e.amount,0))}</span></div><div class="table-wrap"><table><thead><tr><th>支出项目</th><th>金额</th><th>垫付人</th><th>参与人</th><th></th></tr></thead><tbody>${state.expenses.map(e=>`<tr><td>${esc(e.name)}</td><td>${money(e.amount)}</td><td>${esc(member(e.payer))}</td><td>${e.people.map(id=>esc(member(id))).join('、')}</td><td><button class="text" onclick="deleteExpense('${e.id}')">删除</button></td></tr>`).join('')}</tbody></table>${!state.expenses.length?'<div class="empty">还没有支出，记下第一笔共同回忆。</div>':''}</div><p class="explain">仅向实际参与人均摊；金额按分计算，余数依参与人顺序分配。不包含付款、收款或银行转账。</p></section><section class="card"><h2>建议结算</h2><p class="muted">按净余额抵扣，减少互相转账。</p>${settlements().map(s=>`<div class="settle"><span>${esc(member(s.from))} → ${esc(member(s.to))}</span><strong>${money(s.v)}</strong></div>`).join('')||'<div class="empty">目前已平账 ✓</div>'}<p class="explain">此处仅为结算建议，不代表已经付款。</p></section></div><section class="card overview-space"><h2>每个人的账</h2>${Object.entries(balances()).map(([id,b])=>`<div class="row"><span>${esc(member(id))}</span><strong>${b>0?'应收 '+money(b/100):b<0?'应付 '+money(-b/100):'已平账'}</strong></div>`).join('')}</section>`}
function setTab(t){tab=t;render();window.scrollTo({top:0,behavior:'smooth'})}window.setTab=setTab;
function render(){$('#trip-name').textContent=state.title;$('#app').innerHTML=({overview,team,plan,expenses}[tab])();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab))}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
function toggleDone(i){state.done=state.done.includes(i)?state.done.filter(n=>n!==i):[...state.done,i];save()}
function chooseCity(name){if(state.city!==name&&state.events.length&&!confirm('更换目的地将清空原行程，继续吗？'))return;if(state.city!==name)state.events=[];state.city=name;save();toast('已更新意向目的地，请与成员共同确认')}
function tripForm(){modal('设置我们的毕业旅行',`<form id="trip-form"><label>旅行名称<input name="title" maxlength="35" required value="${esc(state.title)}"></label><div class="form-grid"><label>出发日期<input name="start" type="date" required value="${esc(state.start)}"></label><label>旅行天数<input name="days" type="number" min="1" max="14" required value="${state.days}"></label></div><p class="muted">改变天数将清空已有行程，请先导出备份。</p><div class="form-actions"><button class="btn primary">保存设置</button></div></form>`);$('#trip-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(+f.get('days')!==state.days&&state.events.length&&!confirm('天数变更将清空已有行程，继续吗？'))return;if(+f.get('days')!==state.days)state.events=[];state.title=f.get('title').trim()||'我们的毕业旅行';state.start=f.get('start');state.days=+f.get('days');$('#modal').close();save()}}
function memberForm(id){let m=state.members.find(m=>m.id===id)||{name:'',budget:2500,start:state.start,end:state.start,city:state.city,pace:'轻松慢游'};modal(id?'修改成员偏好':'邀请一个新伙伴',`<form id="member-form"><div class="form-grid"><label>称呼<input name="name" maxlength="15" required value="${esc(m.name)}"></label><label>整趟预算上限（元）<input name="budget" type="number" min="1" max="1000000" required value="${m.budget}"></label><label>最早出发<input type="date" name="start" required value="${m.start}"></label><label>最晚返程<input type="date" name="end" required value="${m.end}"></label><label>意向目的地<select name="city">${cities.map(c=>`<option ${c.name===m.city?'selected':''}>${c.name}</option>`).join('')}</select></label><label>旅行节奏<select name="pace">${['轻松慢游','充实打卡'].map(p=>`<option ${p===m.pace?'selected':''}>${p}</option>`).join('')}</select></label></div><div class="form-actions">${id?`<button type="button" class="btn" onclick="removeMember('${id}')">移除成员</button>`:''}<button class="btn primary">保存偏好</button></div></form>`);$('#member-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.end<f.start)return toast('最晚返程不能早于最早出发');if(!f.name.trim())return toast('请填写成员称呼');f.budget=+f.budget;f.id=id||uid();if(id)state.members=state.members.map(m=>m.id===id?f:m);else{if(state.members.length>=30)return toast('雏形最多支持30位成员');state.members.push(f)}$('#modal').close();save();toast('偏好已保存，共识排名已更新')}}
function removeMember(id){if(state.expenses.some(e=>e.payer===id||e.people.includes(id)))return toast('该成员关联账单，请先处理相关账单再移除');state.members=state.members.filter(m=>m.id!==id);$('#modal').close();save()}
const templates={'大理':[['抵达大理，民宿集合','预留交通时间，办理入住',80],['洱海生态廊道骑行','轻装出行，留意天气和骑行安全',60],['大理古城与毕业合照','自由漫步，约定集合地点',40],['喜洲古镇慢游','体验当地小吃，留出休息时间',70]],'杭州':[['抵达杭州，西湖集合','安排集合与入住',50],['西湖漫步与合照','错峰游览，准备防晒和饮水',30],['龙井村喝茶','茶馆消费先确认，注意天气',80],['运河街区散步','自由活动，保留返程时间',40]],'成都':[['抵达成都，民宿集合','安排入住与欢迎晚餐',70],['熊猫基地游览','提前核实门票和预约要求',100],['人民公园喝茶','慢下来聊天，拍一组毕业照',50],['宽窄巷子与街区漫游','餐饮按实际消费，避开高峰',60]]};
function generatePlan(){if(!state.members.length)return toast('先添加成员');if(state.events.length&&!confirm('重新生成将替换现有行程，是否继续？'))return;let slow=state.members.filter(m=>m.pace==='轻松慢游').length>=state.members.length/2;state.events=[];for(let d=1;d<=state.days;d++){let t=templates[state.city][(d-1)%4];state.events.push({id:uid(),day:d,time:'10:00',name:t[0],note:t[1],cost:t[2]},{id:uid(),day:d,time:'14:00',name:slow?'自由探索与休息':'街区探索与拍照',note:'尊重不同体力与兴趣，可自选参与',cost:40});if(d===state.days)state.events.push({id:uid(),day:d,time:'17:00',name:'毕业合照，整理行李与返程',note:'请按各自车次航班调整，预留交通时间',cost:0})}save();toast('已生成可编辑草案，日期与预算冲突仍需共同确认')}
function eventForm(id){let e=state.events.find(e=>e.id===id)||{day:1,time:'09:00',name:'',note:'',cost:0};modal('编辑行程安排',`<form id="event-form"><div class="form-grid"><label>第几天<input name="day" type="number" min="1" max="${state.days}" value="${e.day}" required></label><label>时间<input name="time" type="time" value="${e.time}" required></label><label class="wide">安排名称<input name="name" maxlength="60" value="${esc(e.name)}" required></label><label class="wide">备注<textarea name="note" maxlength="300">${esc(e.note)}</textarea></label><label>参考人均费用<input name="cost" type="number" min="0" max="1000000" step="0.01" value="${e.cost}" required></label></div><div class="form-actions"><button class="btn primary">保存安排</button></div></form>`);$('#event-form').onsubmit=ev=>{ev.preventDefault();let f=Object.fromEntries(new FormData(ev.target));f.id=id||uid();f.day=+f.day;f.cost=+f.cost;if(id)state.events=state.events.map(x=>x.id===id?f:x);else state.events.push(f);$('#modal').close();save()}}
function removeEvent(id){state.events=state.events.filter(e=>e.id!==id);save()}
function expenseForm(){if(!state.members.length)return toast('先添加至少一位成员');modal('记一笔共同支出',`<form id="expense-form"><label>支出项目<input name="name" maxlength="40" required placeholder="例如：包车、民宿、毕业聚餐"></label><div class="form-grid"><label>金额（元）<input name="amount" type="number" min="0.01" max="1000000" step="0.01" required></label><label>谁先垫付<select name="payer">${state.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label></div><p class="muted">谁参与这笔消费？只在勾选成员间均摊。</p><div class="checks">${state.members.map(m=>`<label class="inline"><input type="checkbox" name="people" value="${m.id}" checked>${esc(m.name)}</label>`).join('')}</div><div class="form-actions"><button class="btn primary">保存并更新结算</button></div></form>`);$('#expense-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),people=f.getAll('people');if(!people.length)return toast('至少选择一位参与人');state.expenses.push({id:uid(),name:f.get('name'),amount:+f.get('amount'),payer:f.get('payer'),people});$('#modal').close();save();toast('支出已记录，结算已更新')}}
function deleteExpense(id){if(!confirm('删除这笔支出并重新计算结算？'))return;state.expenses=state.expenses.filter(e=>e.id!==id);save()}
$('#share').onclick=()=>{const encoded=btoa(unescape(encodeURIComponent(JSON.stringify(state)))),url=location.origin+location.pathname+'?trip='+encodeURIComponent(encoded);modal('邀请同学，一起完善计划',`<p class="muted">复制链接分享当前计划快照。同学打开后可在自己的浏览器修改。<strong>当前版本不支持跨设备实时同步</strong>，修改后需要重新分享。</p><label>计划快照链接<textarea id="share-url" rows="3" readonly></textarea></label><button class="btn primary full" id="copy-share">复制邀请链接</button><p class="explain">链接包含当前成员称呼、预算与账单，请仅分享给同行伙伴。笔试提交请使用不带参数的固定首页链接。</p>`);$('#share-url').value=url;$('#copy-share').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('邀请链接已复制')}catch{$('#share-url').select();toast('请手动复制已选中的链接')}}};
$('#export').onclick=()=>{const lines=[`# ${state.title}`,`目的地：${state.city}｜${state.start}｜${state.days}天`,'','## 成员',...state.members.map(m=>`${m.name}：预算${money(m.budget)}，空闲${m.start}至${m.end}`),'','## 行程',...state.events.map(e=>`第${e.day}天 ${e.time} ${e.name}｜${e.note}`),'','## 结算建议',...settlements().map(s=>`${member(s.from)} → ${member(s.to)}：${money(s.v)}`),'','备注：费用为参考估算，景点/交通需自行核实；本文件不代表预订或已付款。'];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));a.download='毕业旅行计划.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('计划已导出')};
$('#about').onclick=()=>modal('关于同路 GradTrip',`<p class="muted">为毕业生解决三件小事：组队信息不集中、偏好难统一、垫付分账容易算错。</p><h3>可以实际操作</h3><p class="muted">成员偏好与时间交集、预算冲突提醒、目的地透明评分、可编辑的规则行程、参与人分账与净额结算、导出与快照分享。</p><h3>雏形边界</h3><p class="muted">本版本使用浏览器本地存储；不含账户、多人实时同步、在线支付、实时票价或真实大模型调用。全部初始成员和账单为演示数据。AI Coding用于构建产品，不代表产品已接入AI服务。</p><button class="btn" id="reset-demo">重置演示数据</button>`);document.addEventListener('click',e=>{if(e.target.id==='reset-demo'&&confirm('重置将清除本机当前计划。继续吗？')){state=seed();$('#modal').close();save();toast('已恢复演示数据')}});render();
